using UnityEngine;using UnityEngine.Rendering;using UnityEngine.XR.Interaction.Toolkit;using UnityEngine.XR.Interaction.Toolkit.Interactables;using LighthouseKeepers.Core;using LighthouseKeepers.Core.Progression;using LighthouseKeepers.Gameplay.Interaction;using LighthouseKeepers.Interaction;using LighthouseKeepers.Lobby;
namespace LighthouseKeepers.WatchDemo {
 public sealed class WatchLantern:MonoBehaviour,IHandPoseTarget,INetworkReleasedBody,INetworkPropRelease {
  public int Slot {get;private set;} public XRGrabInteractable Grab {get;private set;} public bool ReleasedBodyIsKinematic=>!released;public HandPose RequiredPose=>HandPose.WrapGrip;
  public Vector3 Filler=>transform.TransformPoint(LanternMesh.Filler);public bool Held=>Grab.isSelected||lease?.Owner>0;public float Oil=>watch.State.Lanterns?.Oil(Slot)??0;
  WatchDemoController watch;Rigidbody body;INetworkPropStatus lease;HandRig hand;Vector3 home;bool released,usable=true;int lastWick=-1;float dropped,activateAt;Light pool;Transform flame,oil;Renderer[] surfaces;AudioSource sound;AudioClip clunk;Material metal,glass,fire;Mesh mesh,globe,flameMesh;MaterialPropertyBlock block;readonly RaycastHit[] sightHits=new RaycastHit[24];Renderer flameRenderer;
  public static WatchLantern Create(WatchDemoController w,int slot,Vector3 basePosition){var go=new GameObject("KEEPER_OIL_LANTERN_"+slot);go.SetActive(false);go.transform.SetParent(w.transform,false);go.transform.position=basePosition;var l=go.AddComponent<WatchLantern>();l.watch=w;l.Slot=slot;l.home=basePosition;l.Build();go.SetActive(true);return l;}
  void Build(){var p=gameObject.AddComponent<M2StationParts>();p.Initialize();metal=new Material(Resources.Load<Material>("VisualMaterials/Iron")){name="Salt-stained dark lantern tin"};metal.SetColor("_BaseColor",new Color(.19f,.16f,.11f));metal.SetFloat("_Smoothness",.32f);metal.SetColor("_EmissionColor",Color.black);mesh=LanternMesh.Metal();Surface("Pressed tin and bail",mesh,metal);
   glass=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Smoke-stained lantern glass"};glass.SetColor("_BaseColor",new Color(.7f,.67f,.52f,.12f));glass.SetFloat("_Surface",1);glass.SetFloat("_SrcBlend",(int)BlendMode.SrcAlpha);glass.SetFloat("_DstBlend",(int)BlendMode.OneMinusSrcAlpha);glass.SetFloat("_ZWrite",0);glass.SetFloat("_Smoothness",.8f);glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.renderQueue=3000;globe=LanternMesh.Globe();Surface("Glass globe",globe,glass);
   fire=new Material(Shader.Find("Universal Render Pipeline/Simple Lit")){name="Lantern flame"};fire.EnableKeyword("_EMISSION");block=new MaterialPropertyBlock();flameMesh=LanternMesh.Flame();flame=Surface("Oil flame",flameMesh,fire);flameRenderer=flame.GetComponent<Renderer>();
   p.Part("Wick knob",transform,new Vector3(.073f,.075f,-.025f),new Vector3(.025f,.025f,.012f),p.Brass,PrimitiveType.Cylinder).transform.localRotation=Quaternion.Euler(90,0,0);
   p.Part("Oil sight glass recess",transform,new Vector3(0,.045f,-.083f),new Vector3(.025f,.034f,.005f),p.Dark);oil=p.Part("Visible oil level",transform,new Vector3(0,.045f,-.087f),new Vector3(.016f,.028f,.003f),p.Brass).transform;
   pool=new GameObject("Lantern shadowless warm pool").AddComponent<Light>();pool.transform.SetParent(transform,false);pool.transform.localPosition=new Vector3(0,.15f,0);pool.type=LightType.Point;pool.shadows=LightShadows.None;pool.color=new Color(1,.69f,.4f);pool.enabled=false;
   body=gameObject.AddComponent<Rigidbody>();body.mass=.65f;body.isKinematic=true;body.useGravity=true;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;
   var c=gameObject.AddComponent<BoxCollider>();c.center=new Vector3(0,.14f,0);c.size=new Vector3(.18f,.28f,.15f);var bail=gameObject.AddComponent<BoxCollider>();bail.center=LanternMesh.Handle;bail.size=new Vector3(.14f,.07f,.07f);
   foreach(var rig in FindObjectsByType<CharacterController>(FindObjectsSortMode.None)){Physics.IgnoreCollision(c,rig,true);Physics.IgnoreCollision(bail,rig,true);}
   Grab=gameObject.AddComponent<XRGrabInteractable>();Grab.colliders.Add(c);Grab.colliders.Add(bail);Grab.movementType=XRBaseInteractable.MovementType.Kinematic;Grab.attachTransform=M2StationParts.Root("Bail grip",transform,LanternMesh.Handle);Grab.useDynamicAttach=false;Grab.throwOnDetach=false;Grab.smoothPosition=true;Grab.smoothPositionAmount=14;Grab.smoothRotation=true;Grab.smoothRotationAmount=10;Grab.selectEntered.AddListener(Hold);Grab.selectExited.AddListener(Release);Grab.activated.AddListener(Wick);
   surfaces=GetComponentsInChildren<Renderer>();sound=gameObject.AddComponent<AudioSource>();sound.playOnAwake=false;sound.spatialBlend=1;sound.minDistance=.25f;sound.maxDistance=8;sound.dopplerLevel=0;KeeperAudioMix.Route(sound,"SFX_World");clunk=Resources.Load<AudioClip>("Hands/clunk");}
  Transform Surface(string name,Mesh m,Material material){var g=new GameObject(name);g.transform.SetParent(transform,false);g.AddComponent<MeshFilter>().sharedMesh=m;var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=material;r.shadowCastingMode=ShadowCastingMode.Off;return g.transform;}
  void Hold(SelectEnterEventArgs e){if(PlayerPrefs.GetInt("LK.Lantern.InputLearned",0)==0){watch.GetComponent<ObjectiveHud>()?.ShowHint(KeeperStrings.Get("lantern.firstGrip"),8);PlayerPrefs.SetInt("LK.Lantern.InputLearned",1);PlayerPrefs.Save();}hand=e.interactorObject.transform.GetComponentInParent<HandRig>();hand?.SetPose(RequiredPose,this);hand?.Pulse(.2f,.04f);}
  void Release(SelectExitEventArgs e){hand?.ClearPose();hand=null;OnNetworkReleased();}
  public void OnNetworkReleased(){released=true;dropped=Time.time;}
  void Wick(ActivateEventArgs e){if(!Grab.isSelected||Time.time<activateAt||watch.Sleeping||watch.State.Failed)return;activateAt=Time.time+.25f;if(watch.State.Coop!=null)watch.State.Coop.Send(CoopAction.LanternWick,Slot,true);else watch.State.CycleLantern(Slot);}
  void Update(){lease??=GetComponent<INetworkPropStatus>();var state=watch.State.Lanterns;bool active=state!=null;
   if(usable!=active){foreach(var r in surfaces)r.enabled=active;foreach(var c in Grab.colliders)c.enabled=active;Grab.enabled=active;usable=active;}
   bool lit=active&&state.Lit(Slot);pool.enabled=lit&&!watch.Sleeping&&!watch.State.Failed;var wick=state?.Wick(Slot)??LanternWick.Off;
   pool.range=wick==LanternWick.High?watch.State.Sprint5.lanternHighRange:watch.State.Sprint5.lanternLowRange;
   float flicker=1+.06f*Mathf.Sin(Time.time*2.7f+Slot)*Mathf.Sin(Time.time*1.3f);float fuel=Mathf.InverseLerp(0,.2f,Oil);pool.intensity=(wick==LanternWick.High?1.25f:.65f)*flicker*Mathf.Lerp(.25f,1,fuel);
   block.SetColor("_BaseColor",lit?new Color(.9f,.45f,.06f):new Color(.08f,.04f,.015f));block.SetColor("_EmissionColor",lit?new Color(1,.42f,.04f)*3*flicker*fuel:Color.black);flameRenderer.SetPropertyBlock(block);flame.gameObject.SetActive(lit);oil.localScale=new Vector3(.016f,.028f*Mathf.Max(.02f,Oil),.003f);oil.localPosition=new Vector3(0,.031f+.014f*Oil,-.087f);
   if(lastWick!=(int)wick){if(lastWick>=0&&clunk)sound.PlayOneShot(clunk,.12f);hand?.Pulse(.18f,.04f);lastWick=(int)wick;}
   if(!Held&&(lease==null||lease.CanSimulateReleased)&&released){body.isKinematic=false;var hook=watch.NearestLanternHook(transform.TransformPoint(LanternMesh.Handle));if(hook.HasValue)SetRest(hook.Value-LanternMesh.Handle);else if(Time.time-dropped>20||transform.position.y<-.8f)SetRest(home);}
   if(!watch.State.ReadOnly&&active)ObserveRepulsion();
  }
  void ObserveRepulsion(){var d=watch.State.Drowned;bool present=d?.Phase==DrownedPhase.Manifest&&d.Anchored;var target=present?new Vector3(d.X,d.Y+1.2f,d.Z):Vector3.zero;var from=pool.transform.position;var delta=target-from;float range=watch.State.Sprint5.lanternHighRange;bool aim=present&&delta.sqrMagnitude<range*range&&Vector3.Dot(transform.forward,delta.normalized)>.7f;
   if(aim){int count=Physics.RaycastNonAlloc(from,delta.normalized,sightHits,delta.magnitude,~0,QueryTriggerInteraction.Ignore);if(count==sightHits.Length)aim=false;for(int i=0;i<count&&aim;i++){var h=sightHits[i];if(!h.transform.IsChildOf(transform)&&!h.collider.GetComponentInParent<HandRig>()&&!h.collider.GetComponentInParent<Unity.XR.CoreUtils.XROrigin>())aim=false;}}
   watch.State.RepelWithLantern(Slot,Time.deltaTime,Held,aim);}
  void SetRest(Vector3 p){if(!body.isKinematic)body.linearVelocity=body.angularVelocity=Vector3.zero;released=false;body.isKinematic=true;body.position=p;body.rotation=Quaternion.identity;if(clunk)sound.PlayOneShot(clunk,.12f);}
  void OnDestroy(){foreach(var m in new[]{metal,glass,fire})if(m)Destroy(m);if(mesh)Destroy(mesh);if(globe)Destroy(globe);if(flameMesh)Destroy(flameMesh);}
 }
}
